import{_ as r,o as e,c as t,a2 as i}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"一般設定","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/user-guide/settings/general.md","filePath":"zh-TW/user-guide/settings/general.md","lastUpdated":1788247711000}'),n={name:"zh-TW/user-guide/settings/general.md"};function a(s,o,l,d,g,c){return e(),t("div",null,[...o[0]||(o[0]=[i('<h1 id="一般設定" tabindex="-1">一般設定 <a class="header-anchor" href="#一般設定" aria-label="Permalink to &quot;一般設定&quot;">​</a></h1><p>一般設定涵蓋系統的核心執行行為、搜尋視窗外觀與配置參數、各結果類型的優先順序權重以及預覽元件的排程順序。頁面頂部共分為六個索引標籤頁：<strong>系統</strong>、<strong>快速搜尋視窗</strong>、<strong>完整搜尋視窗</strong>、<strong>預覽視窗</strong>、<strong>快速導覽</strong>與<strong>預覽與縮圖</strong>。</p><h2 id="_1-系統-system" tabindex="-1">1. 系統（System） <a class="header-anchor" href="#_1-系統-system" aria-label="Permalink to &quot;1. 系統（System）&quot;">​</a></h2><ul><li><strong>開機自動啟動 Lertaro</strong>：勾選後在 Windows 使用者登入時自動啟動 Lertaro。</li><li><strong>啟動時自動檢查更新</strong>：勾選後在軟體每次啟動時自動連線查詢最新版本。</li><li><strong>自動無訊息更新</strong>：僅在開啟「檢查更新」時可用。偵測到新版本後將在背景無訊息下載並自動無縫覆蓋升級，免去手動操作。</li><li><strong>啟用硬體加速</strong>：預設開啟。若遇到筆記型電腦獨立顯示卡（如 NVIDIA Advanced Optimus）因 Lertaro 常駐而無法自動休眠切換內建顯示卡的問題，可關閉該項改用軟體轉譯。修改後需重啟 Lertaro 生效。</li><li><strong>隱藏系統匣圖示</strong>：勾選後隱藏 Windows 工作列右下角的系統匣圖示。快速搜尋視窗內的 Logo 圖示依然能呼出完整的系統功能表，不會遺失任何入口。</li><li><strong>啟用 Everything 相容服務 (IPC)</strong>：預設關閉。開啟後，Lertaro 會在背景模擬標準 Everything Win32 IPC 通訊協定介面，讓 Directory Opus、Total Commander 等第三方軟體無需額外安裝執行 Everything 即可直接呼叫 Lertaro 的極速記憶體索引。</li><li><strong>啟用模糊比對</strong>：預設開啟。開啟時支援跳躍字元模糊比對；關閉後要求普通查詢詞必須為連續子字串（詳見<a href="./../search-syntax.html"><strong>搜尋語法</strong></a>）。即時生效無需重啟。</li><li><strong>查詢標記總引導字元</strong>：單字元文字方塊（預設為 <code>:</code>）。用於設定搜尋框尾部後綴切分標記（如 <code>:.pdf</code>、<code>:@doc</code>、<code>:[S]</code>）的總引導符號。</li><li><strong>記錄等級</strong>：下拉選擇「錯誤 / 警告 / 資訊 (預設) / 偵錯」，控制系統各處理程序記錄輸出的詳細程度。</li><li><strong>介面語言</strong>：下拉選擇 Lertaro 的全域顯示語言。</li></ul><h2 id="_2-快速搜尋視窗-quick-search-window" tabindex="-1">2. 快速搜尋視窗（Quick Search Window） <a class="header-anchor" href="#_2-快速搜尋視窗-quick-search-window" aria-label="Permalink to &quot;2. 快速搜尋視窗（Quick Search Window）&quot;">​</a></h2><p>本索引標籤頁用於精細化設定快速置中浮動視窗的幾何尺寸與結果排序：</p><h3 id="搜尋列配置" tabindex="-1">搜尋列配置 <a class="header-anchor" href="#搜尋列配置" aria-label="Permalink to &quot;搜尋列配置&quot;">​</a></h3><ul><li><strong>搜尋列寬度 (像素)</strong>：取值範圍 <code>300–1200px</code>，預設 <code>570px</code>。</li><li><strong>搜尋列高度 (像素)</strong>：取值範圍 <code>45–120px</code>，預設 <code>60px</code>。該數值會按比例同步驅動結果清單的圖示大小、行高與字型大小，確保視覺協調。</li><li><strong>搜尋框內顯示時鐘</strong>：開啟後，在搜尋框為空時將提示文字替換為目前即時日期、星期與時間。輸入文字後時鐘自動隱藏。</li><li><strong>再次按下快速鍵時開啟完整視窗</strong>：開啟後，在快速視窗已顯示狀態下再次按下全域呼出快速鍵，將攜帶目前輸入內容直接切換至完整主搜尋視窗。</li><li><strong>鎖定位置</strong>：開啟後禁止滑鼠拖曳移動快速視窗，防止誤觸改變位置。</li><li><strong>自動將剪貼簿文字填入快速搜尋框</strong>：預設關閉。快速視窗在沒有預填內容時，如果剪貼簿中有新的非空文字，就將其用作搜尋內容。手動貼上和其他視窗不受影響。</li><li><strong>重設配置設定</strong>：一鍵將快速視窗尺寸與配置恢復為系統初始預設值。</li></ul><h3 id="結果類型優先順序與觸發符" tabindex="-1">結果類型優先順序與觸發符 <a class="header-anchor" href="#結果類型優先順序與觸發符" aria-label="Permalink to &quot;結果類型優先順序與觸發符&quot;">​</a></h3><ul><li><strong>優先順序排序清單</strong>：支援拖曳左側手柄或上下移動各結果類型（應用程式、系統設定、檔案、外掛模組擴充項目等）。排在前面的類型在綜合搜尋結果中享有更高的排列權重。</li><li><strong>專屬單字元觸發符</strong>：可為特定結果類型設定專屬單字元前綴（如將檔案篩選器設為 <code>;</code>）。在搜尋框開頭輸入該字元即可直接過濾出該類型的專屬結果。</li></ul><h2 id="_3-完整搜尋視窗-full-search-window" tabindex="-1">3. 完整搜尋視窗（Full Search Window） <a class="header-anchor" href="#_3-完整搜尋視窗-full-search-window" aria-label="Permalink to &quot;3. 完整搜尋視窗（Full Search Window）&quot;">​</a></h2><p>用於設定大尺寸主搜尋視窗（<code>Ctrl+F</code>）的預設行為與表格檢視：</p><ul><li><strong>視窗寬度 / 高度 (像素)</strong>：寬度範圍 <code>640–2000px</code>（預設 <code>854px</code>），高度範圍 <code>400–1400px</code>（預設 <code>480px</code>）。</li><li><strong>僅允許一個完整搜尋視窗</strong>：開啟後，再次開啟完整視窗將直接啟用已有執行個體，避免重複建立多開。</li><li><strong>重設搜尋視窗設定</strong>：一鍵恢復主視窗預設寬高設定。</li><li><strong>結果表格欄順序</strong>：拖曳自訂表格檢視中各欄（名稱、路徑、修改時間等）的先後排列順序。</li><li><strong>側邊欄篩選順序</strong>：拖曳調整主視窗左側分類篩選欄的展示順序；篩選欄會即時動態呈現目前關鍵字在各分類下的比對項目數量。</li><li><strong>動作功能表分組順序</strong>：拖曳調整快顯動作功能表（<code>Ctrl+O</code>）中各功能分組的顯示先後。</li></ul><h2 id="_4-預覽視窗-preview-window" tabindex="-1">4. 預覽視窗（Preview Window） <a class="header-anchor" href="#_4-預覽視窗-preview-window" aria-label="Permalink to &quot;4. 預覽視窗（Preview Window）&quot;">​</a></h2><ul><li><strong>預覽視窗寬度 / 高度 (像素)</strong>：寬度範圍 <code>250–900px</code>，高度範圍 <code>250–1200px</code>。</li><li><strong>重設預覽視窗設定</strong>：將 QuickLook 預覽浮動視窗的尺寸重設為標準預設比例。系統會自動計算避免預覽視窗超出目前顯示器的工作可視區域。</li></ul><h2 id="_5-快速導覽-quick-navigation" tabindex="-1">5. 快速導覽（Quick Navigation） <a class="header-anchor" href="#_5-快速導覽-quick-navigation" aria-label="Permalink to &quot;5. 快速導覽（Quick Navigation）&quot;">​</a></h2><ul><li><strong>提供者順序</strong>：透過上下箭頭或拖曳手柄，調整滑鼠快速導覽階層式功能表根層級各個資料來源提供者（我的最愛、搜尋歷程記錄、已開啟資料夾、第三方管理器書籤等）的分組排列順序。</li></ul><h2 id="_6-預覽與縮圖-previews-thumbnails" tabindex="-1">6. 預覽與縮圖（Previews &amp; Thumbnails） <a class="header-anchor" href="#_6-預覽與縮圖-previews-thumbnails" aria-label="Permalink to &quot;6. 預覽與縮圖（Previews &amp; Thumbnails）&quot;">​</a></h2><ul><li><strong>檔案預覽提供者順序</strong>：調整多個預覽外掛模組（如內建富文字/媒體解碼器與第三方 QuickLook 橋接）的呼叫優先順序。</li><li><strong>縮圖提供者順序</strong>：調整結果清單中檔案圖示與縮圖擷取元件的呼叫優先順序。</li></ul>',19)])])}const p=r(n,[["render",a]]);export{u as __pageData,p as default};
